const input=$json.body??$json;
const msg=String(input.seller_response||input.message||input.inbound_message||"").trim();
const text=msg.toLowerCase();
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const dnc=Boolean(input.dnc||input.do_not_contact);
let classification="other_response",route="WF-292",human=false,reason="response requires standard negotiation analysis";
if(dnc){classification="dnc_request";route="WF-126";human=true;reason="seller requested or is marked do-not-contact";}
else if(!msg){classification="no_response";route="WF-290";reason="no seller message was supplied";}
else if(/\\b(no|not interested|stop|remove me|do not contact|don't contact|leave me alone)\\b/i.test(text)){classification="rejected";route="WF-261";human=true;reason="seller rejected or requested contact cessation";}
else if(/\\b(yes|accept|accepted|deal|let's do it|sounds good|i agree|agreed)\\b/i.test(text)){classification="accepted";route="WF-292";human=true;reason="seller appears to accept the proposed terms";}
else if(/\\b(offer|price|counter|would you do|can you do|i need|i want)\\b/i.test(text)){classification="counteroffer_or_price_question";route="WF-292";human=true;reason="seller response appears price/offer related";}
else if(/\\b(what|how|when|where|why|can you explain|question)\\b/i.test(text)){classification="question";route="WF-292";reason="seller asked for clarification";}
if(blockers.length){route="WF-126";human=true;reason="active deal blockers require review";}
const nums=(msg.match(/\\$?\\d[\\d,]*(?:\\.\\d+)?/g)||[]).map(v=>Number(v.replace(/[$,]/g,""))).filter(Number.isFinite);
const counteroffer=nums.length?nums[0]:null;
const idempotencyKey=input.idempotency_key||`wf-296:${input.dispatch_id||input.deal_id||"unknown"}:${input.provider_event_id||input.version||1}`;
return [{json:{...input,workflow:"WF-296",workflow_name:"Seller Response → AI Classification & Negotiation Routing Controller",status:classification==="dnc_request"?"blocked_dnc":classification==="no_response"?"no_response":"response_classified",seller_response_analysis:{classification,confidence:msg?0.75:1.0,reason,counteroffer_amount:counteroffer,message_present:Boolean(msg)},next_workflow:route,human_review_required:human,audit:{event_type:"ai_seller_response_classification",idempotency_key:idempotencyKey}}}];
